DECLARE @product_name NVARCHAR(500) = N'{{ ($json.product_name || "").replace(/'/g, "''") }}';
DECLARE @item_id VARCHAR(50) = '{{ ($json.item_id || "").replace(/'/g, "''") }}';
DECLARE @ingredients NVARCHAR(1000) = N'{{ ($json.ingredients || "").replace(/'/g, "''") }}';
DECLARE @main_uses NVARCHAR(MAX) = N'{{ ($json.main_uses || "").replace(/'/g, "''") }}';
DECLARE @target_patients NVARCHAR(500) = N'{{ ($json.target_patients || "").replace(/'/g, "''") }}';
DECLARE @usage_instructions NVARCHAR(1000) = N'{{ ($json.usage_instructions || "").replace(/'/g, "''") }}';
DECLARE @contraindications NVARCHAR(1000) = N'{{ ($json.contraindications || "").replace(/'/g, "''") }}';
DECLARE @side_effects NVARCHAR(1000) = N'{{ ($json.side_effects || "").replace(/'/g, "''") }}';
DECLARE @keywords NVARCHAR(1000) = N'{{ ($json.keywords || "").replace(/'/g, "''") }}';
DECLARE @confidence VARCHAR(20) = '{{ ($json.confidence || "").replace(/'/g, "''") }}';
DECLARE @content NVARCHAR(MAX) = N'{{ ($json.content || "").replace(/'/g, "''") }}';
DECLARE @extracted_json NVARCHAR(MAX) = N'{{ ($json.extracted_json || "").replace(/'/g, "''") }}';

DECLARE @MatchedItemID VARCHAR(50) = NULL;

IF NULLIF(@item_id, '') IS NOT NULL
BEGIN
    SELECT TOP 1 @MatchedItemID = ItemID FROM CF_ItemTbl WHERE ItemID = @item_id;
END

IF @MatchedItemID IS NULL
BEGIN
    SELECT TOP 1 @MatchedItemID = ItemID 
    FROM CF_ItemTbl 
    WHERE ItemName LIKE '%' + @product_name + '%' 
       OR @product_name LIKE '%' + ItemName + '%';
END

IF @MatchedItemID IS NULL
BEGIN
    SET @MatchedItemID = 'OCR_' + REPLACE(REPLACE(REPLACE(LOWER(@product_name), ' ', '_'), '-', '_'), '.', '_');
END

IF EXISTS (SELECT 1 FROM AI_ProductKnowledgeTbl WHERE ItemID = @MatchedItemID)
BEGIN
    UPDATE AI_ProductKnowledgeTbl
    SET Ingredients = @ingredients,
        MainUses = @main_uses,
        TargetPatients = @target_patients,
        UsageInstructions = @usage_instructions,
        Contraindications = @contraindications,
        SideEffects = @side_effects,
        Keywords = @keywords,
        Confidence = @confidence,
        SourceText = @content,
        ExtractedJson = @extracted_json,
        Status = 'Pending',
        DateUpdate = GETDATE()
    WHERE ItemID = @MatchedItemID;
END
ELSE
BEGIN
    INSERT INTO AI_ProductKnowledgeTbl (
        ItemID, Ingredients, MainUses, TargetPatients, UsageInstructions, 
        Contraindications, SideEffects, Keywords, Confidence, SourceText, 
        ExtractedJson, Status, VersionNo, DateUpdate
    )
    VALUES (
        @MatchedItemID, @ingredients, @main_uses, @target_patients, @usage_instructions,
        @contraindications, @side_effects, @keywords, @confidence, @content,
        @extracted_json, 'Pending', 1, GETDATE()
    );
END

SELECT @MatchedItemID AS ItemID, 'Pending' AS Status, @product_name AS ProductName;

