parameters.jsCode:
const inputJson = $json || {};
const headers = inputJson.headers || {};
const method = inputJson.method || headers['x-forwarded-method'] || 'POST';
const body = inputJson.body || {};
let dsVal = body.DataSourceValue || '';
let searchKey = body.SearchKey || '';

if (!headers.authorization && headers.cookie) {
  const m = headers.cookie.match(/(?:^|; )auth_token=([^;]+)/);
  if (m) headers.authorization = 'Bearer ' + m[1];
}

dsVal = dsVal.replace(/'/g, "''");
searchKey = searchKey.replace(/'/g, "''");

return [{ json: { ...inputJson, headers: headers, body: {...body, DataSourceValueSafe: dsVal, SearchKeySafe: searchKey}, _method: method.toUpperCase() } }];

// --- W1 FIX: Convention-based auth detection ---
// Tất cả SP có tên kết thúc bằng _AI đều cần @Username.
// Không còn hardcode list. Thêm SP mới -> tự động được auth nếu đặt tên đúng quy ước.
// Nếu SP ngoài quy ước nhưng vẫn cần auth: thêm vào EXTRA_AUTH_LIST bên dưới.
const EXTRA_AUTH_LIST = []; // Ví dụ: ['API_BaoCaoThuong']

function needsAuth(spName) {
  if (!spName) return false;
  if (/_AI$/i.test(spName)) return true;           // Convention: kết thúc _AI → luôn cần auth
  return EXTRA_AUTH_LIST.indexOf(spName) !== -1;   // Danh sách bổ sung nếu có
}

// Build DataSource SQL
const dsNode = $('Check Method DataSource').first().json;
let dsVal = dsNode.body.DataSourceValueSafe || '';
const searchKey = dsNode.body.SearchKeySafe || '';

// Lay username tu body hoac decode JWT
let username = dsNode.body.username || '';
if (!username) {
  try {
    const authH = (dsNode.headers || {}).authorization || (dsNode.headers || {}).Authorization || '';
    const tm = authH.match(/Bearer (.+)/);
    if (tm) {
      const b64 = tm[1].split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
      const pad = (4 - b64.length % 4) % 4;
      const pl = JSON.parse(Buffer.from(b64 + '='.repeat(pad), 'base64').toString('utf8'));
      username = pl.username || pl.Username || pl.sub || pl.name || '';
    }
  } catch(e) { username = ''; }
}

if (!dsVal) return [{ json: { query: "SELECT 1 AS code, 'Empty DataSource' AS msg FOR JSON PATH;" } }];

const parts = dsVal.split('|');
let spName = parts[0].trim();

const mapper = {
  '@danh_muc': 'API_DanhMuc_Core_AI',
  '@tra_cuu_san_pham': 'API_TraCuuSanPham_AI',
  '@san_pham': 'API_TraCuuSanPham_AI'
};
if (mapper[spName.toLowerCase()]) spName = mapper[spName.toLowerCase()];

if (!(/^(API_|sp_|@)/i.test(spName))) {
  return [{ json: { query: "SELECT 1 AS code, 'Invalid SP Name' AS msg FOR JSON PATH;" } }];
}

let query = `EXEC ${spName.replace(/[^a-zA-Z0-9_@]/g, '')}`;
let params = [];
let usedQ = false;
let usedUsername = false;

for (let i = 1; i < parts.length; i++) {
  const p = parts[i].split('=');
  if (p.length === 2) {
    const pKey = p[0].trim().replace(/[^a-zA-Z0-9_@]/g, '');
    let pVal = p[1].trim();
    if (pVal.includes('{q}')) { pVal = pVal.replace('{q}', searchKey); usedQ = true; }
    if (pVal.includes('{username}')) { pVal = pVal.replace('{username}', username); usedUsername = true; }
    params.push(`${pKey} = N'${pVal}'`);
  }
}

// W1 FIX: Dùng needsAuth() thay vì list hardcode
if (!usedUsername && username && needsAuth(spName)) {
  params.unshift(`@Username = N'${username.replace(/'/g, "''")}'`);
}

if (searchKey && !usedQ) {
  params.push(`@timkiem = N'${searchKey}'`);
}

if (params.length) query += ' ' + params.join(', ');
query += ';';

return [{ json: { query } }];

const inputJson = $json || {};
// --- TÍCH HỢP TƯƠNG THÍCH AGENT ---
let body = inputJson.body || {};
const isAgent = (inputJson.sessionId && inputJson.intent) || (body.sessionId && body.intent) || inputJson._isAgent || body._isAgent;
let headers = inputJson.headers || {};
let method = inputJson.method || headers['x-forwarded-method'] || 'POST';

if (isAgent) {
    body = { ...inputJson, ...body };
    body.ApiCode = body.intent || inputJson.intent; // Agent gọi tool dùng intent
    body.params = { ...inputJson, ...body.params };
    method = 'POST'; // Bỏ qua OPTIONS check
    if (inputJson.authorization || body.authorization) headers.authorization = inputJson.authorization || body.authorization;
    if (inputJson.cookie || body.cookie) headers.cookie = inputJson.cookie || body.cookie;
}
// ---------------------------------
let apiCode = body.ApiCode || body.StoredProcedure || '';


if (!headers.authorization || headers.authorization.trim() === '' || headers.authorization.includes('empty') || headers.authorization.includes('null')) {
  if (headers.cookie) {
    const m = headers.cookie.match(/(?:^|; )auth_token=([^;]+)/);
    if (m) headers.authorization = 'Bearer ' + m[1];
  }
}

if (!/^@[a-zA-Z0-9_]+$/.test(apiCode)) {
  apiCode = '@invalid_code';
}

const params = body.params || {};
let username = body.username || '';
if (!username) {
  try {
    const authH = headers.authorization || headers.Authorization || '';
    const tm = authH.match(/Bearer (.+)/);
    if (tm) {
      const token = tm[1];

      // --- 1. LOCAL EXPIRATION CHECK FOR JWT ---
      if (token.includes('.')) {
        try {
          const b64 = token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
          const pad = (4 - b64.length % 4) % 4;
          const pl = JSON.parse(Buffer.from(b64 + '='.repeat(pad), 'base64').toString('utf8'));
          if (pl && pl.exp) {
            const nowSecs = Math.floor(Date.now() / 1000);
            if (nowSecs > pl.exp) {
              throw new Error("SECURITY_ALERT: Token đăng nhập đã hết hạn (Expired). Vui lòng đăng nhập lại!");
            }
          }
        } catch(e) {
          if (e.message && e.message.includes('SECURITY_ALERT')) throw e;
        }
      }

      // --- 2. VERIFY SIGNATURE (API_UserInfo) OR CACHE ---
      // We NEVER trust the JWT payload's username directly. 
      // It MUST be validated by the backend at least once to ensure signature is correct.
      try {
        const staticData = $getWorkflowStaticData('global');
        if (!staticData.uuidCache) staticData.uuidCache = {};

        // W4 FIX: Cleanup uuidCache entries quá TTL 8 giờ (tránh memory leak)
        const UUID_TTL = 8 * 3600 * 1000;
        const nowMs = Date.now();
        if (!staticData.uuidCacheTs) staticData.uuidCacheTs = {};
        for (const tk of Object.keys(staticData.uuidCacheTs)) {
          if ((nowMs - staticData.uuidCacheTs[tk]) > UUID_TTL) {
            delete staticData.uuidCache[tk];
            delete staticData.uuidCacheTs[tk];
          }
        }

        if (staticData.uuidCache[token] && staticData.uuidCacheTs[token] && (nowMs - staticData.uuidCacheTs[token]) < UUID_TTL) {
            username = staticData.uuidCache[token]; // Already verified by backend previously
        } else {
            // Cache miss hoặc expired → gọi lại API_UserInfo để verify
            delete staticData.uuidCache[token];
            delete staticData.uuidCacheTs[token];
            inputJson._uuidToken = token;
        }
      } catch(err) {
        inputJson._uuidToken = token;
      }
    }
  } catch(e) { 
    if (e.message && e.message.includes('SECURITY_ALERT')) throw e;
    username = '';
  }
}

if (username && !params['@Username']) {
  params['@Username'] = username;
}


// --- BẮT ĐẦU VÁ BẢO MẬT: REGEX VALIDATOR ---
const sqlBlacklist = /(\bDROP\s+TABLE\b|\bTRUNCATE\s+TABLE\b|\bUNION\s+SELECT\b)/i;
for (const key in params) {
  if (Object.prototype.hasOwnProperty.call(params, key)) {
    const val = String(params[key]);
    if (sqlBlacklist.test(val)) {
      apiCode = '@invalid_code'; // Đổi mã thành invalid để chặn lệnh SQL
      params['@SecurityBlock'] = 'Phát hiện từ khóa nghi ngờ SQL Injection: ' + val;
    }
  }
}
// --- KẾT THÚC VÁ BẢO MẬT ---

const paramsSafeStr = JSON.stringify(params).replace(/'/g, "''");

return [{ json: { _isAgent: isAgent, ...inputJson, headers: headers, body: {...body, ApiCode: apiCode, params: params}, _paramsSafeStr: paramsSafeStr, _method: method.toUpperCase() } }];

const execNode = $('Check Method Execute').first().json;
const apiCode = execNode.body.ApiCode || '@invalid_code';
let paramsStr = execNode._paramsSafeStr || '{}';

let realUsername = '';
try {
    let data = $json || {};
    if (data.data) data = data.data;
    if (data.Data) data = data.Data;
    if (data.records && Array.isArray(data.records) && data.records.length > 0) data = data.records[0];

    realUsername = data.username || data.Username || data.UserName || data.name || data.sub || data.User || '';
    if (!realUsername && execNode._uuidToken) {
        try {
            const b64 = execNode._uuidToken.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
            const pad = (4 - b64.length % 4) % 4;
            const pl = JSON.parse(Buffer.from(b64 + '='.repeat(pad), 'base64').toString('utf8'));
            realUsername = pl.username || pl.Username || pl.UserName || pl.sub || pl.name || '';
        } catch(jwtErr) {}
    }
    if (realUsername && execNode._uuidToken) {
        const staticData = $getWorkflowStaticData('global');
        if (!staticData.uuidCache) staticData.uuidCache = {};
        staticData.uuidCache[execNode._uuidToken] = realUsername;
    }
} catch(e) {}

// ĐÃ XÓA FAILSAFE ADMIN ĐỂ ĐẢM BẢO BẢO MẬT TUYỆT ĐỐI

try {
    let p = JSON.parse(paramsStr.replace(/''/g, "'")); // Un-escape first

    // XÓA CÁC THAM SỐ NULL ĐỂ KHÔNG LÀM HỎNG SQL
    for (let k in p) {
        if (p[k] === null) {
            delete p[k];
        }
    }

    // CHỈ NẠP USERNAME KHI TOKEN THẬT SỰ CÓ DỮ LIỆU
    if (realUsername) p['@Username'] = realUsername;

    paramsStr = JSON.stringify(p).replace(/'/g, "''"); // Re-escape
} catch(e) {
    if (realUsername) {
        try {
            const cleanStr = paramsStr.trim();
            if (cleanStr.endsWith('}')) {
                paramsStr = cleanStr.substring(0, cleanStr.length - 1) + ", \"@Username\":\"" + realUsername.replace(/'/g, "''") + "\"}";
            }
        } catch(err) {}
    }
}

const query = `
DECLARE @ApiCode VARCHAR(100) = '${apiCode}';
DECLARE @ParamsJSON NVARCHAR(MAX) = N'${paramsStr}';

-- GLOBAL SMART CUSTOMER RESOLUTION (NAME TO ID)
DECLARE @MaKhachHang NVARCHAR(100) = '';
IF ISJSON(@ParamsJSON) = 1
BEGIN
    SELECT @MaKhachHang = [value] FROM OPENJSON(@ParamsJSON) WHERE [key] IN ('@MaKhachHang', '@ObjectID');
END

IF @MaKhachHang <> '' AND NOT EXISTS (SELECT 1 FROM dbo.CF_ObjectTbl WHERE ObjectID = @MaKhachHang)
BEGIN
    DECLARE @ResolvedID VARCHAR(50) = ''
    DECLARE @CleanSearch NVARCHAR(100) = REPLACE(dbo.ufn_remove_accents(@MaKhachHang), ' ', '')

    SELECT TOP 1 @ResolvedID = ObjectID 
    FROM dbo.CF_ObjectTbl 
    WHERE REPLACE(dbo.ufn_remove_accents(ObjectName), ' ', '') LIKE '%' + @CleanSearch + '%'
       OR ObjectID LIKE '%' + @CleanSearch + '%'
    ORDER BY 
        CASE WHEN ObjectID = @CleanSearch THEN 1
             WHEN REPLACE(dbo.ufn_remove_accents(ObjectName), ' ', '') = @CleanSearch THEN 2
             WHEN REPLACE(dbo.ufn_remove_accents(ObjectName), ' ', '') LIKE @CleanSearch + '%' THEN 3
             ELSE 4
        END,
        COALESCE((SELECT MAX(DocumentDate) FROM AR_InvoiceTbl WHERE ObjectID = CF_ObjectTbl.ObjectID), '1900-01-01') DESC,
        LEN(ObjectName) ASC;

    IF @ResolvedID <> ''
    BEGIN
        SET @ParamsJSON = JSON_MODIFY(@ParamsJSON, '$."@MaKhachHang"', @ResolvedID);
        SET @ParamsJSON = JSON_MODIFY(@ParamsJSON, '$."@ObjectID"', @ResolvedID);
    END
END

IF @ApiCode = '@lap_don_hang'
BEGIN
    DECLARE @CartMaKH NVARCHAR(100) = '';
    DECLARE @ItemList NVARCHAR(MAX) = '[]';
    IF ISJSON(@ParamsJSON) = 1
    BEGIN
        SELECT @CartMaKH = [value] FROM OPENJSON(@ParamsJSON) WHERE [key] IN ('@MaKhachHang', '@ObjectID');
        SELECT @ItemList = [value] FROM OPENJSON(@ParamsJSON) WHERE [key] = '@ItemList';
    END

    SELECT 
        0 AS [code], 
        N'Dạ, em đang chuẩn bị giỏ hàng lên đơn cho khách hàng. Sếp kiểm tra lại thông tin trong bảng nhé!' AS [msg], 
        'CART' AS [Metadata_UiTemplate],
        @CartMaKH AS [MaKhachHang],
        @ItemList AS [ItemList];
    RETURN;
END

DECLARE @SPName NVARCHAR(MAX);
DECLARE @UiTemplate VARCHAR(50) = 'DEFAULT';

SELECT @SPName = StoredProcedure, @UiTemplate = ISNULL(UiTemplate, 'DEFAULT') FROM dbo.API_Definition WHERE ApiCode = @ApiCode AND IsActive = 1;

IF @SPName IS NULL
BEGIN
    SELECT 2 AS code, 'Missing para or Object not support' AS msg, 'DEFAULT' AS uiTemplate FOR JSON PATH;
    RETURN;
END

SELECT @UiTemplate AS Metadata_UiTemplate; -- Meta set

DECLARE @SQL NVARCHAR(MAX) = N'EXEC ' + QUOTENAME(@SPName) + N' ';

IF @ParamsJSON IS NOT NULL AND @ParamsJSON != '' AND @ParamsJSON != '{}'
BEGIN
    SELECT @SQL = @SQL + [key] + 
        CASE WHEN [type] = 0 THEN ' = NULL, '
             ELSE N' = N''' + REPLACE(CAST([value] AS NVARCHAR(MAX)), '''', '''''') + N''', ' END
    FROM OPENJSON(@ParamsJSON)
    WHERE [key] LIKE '@%'
      AND [key] COLLATE DATABASE_DEFAULT IN (SELECT name COLLATE DATABASE_DEFAULT FROM sys.parameters WHERE object_id = OBJECT_ID(@SPName));

    IF RIGHT(@SQL, 2) = ', ' SET @SQL = LEFT(@SQL, LEN(@SQL) - 1);
END

EXEC sp_executesql @SQL;
`.trim();

return [{ json: { query, debug_username: realUsername, debug_api_response: $json } }];

const items = $input.all();

if (!items || items.length === 0) {
  return [{ json: { reply: 'Khong tim thay du lieu', status: 'success', count: 0, data: [], uiTemplate: uiTemplate } }];
}

const JSON_KEY = 'JSON_F52E2B61-18A1-11d1-B105-00805F49916B';
let payload = items.map(i => i.json);
// --- UPDATE ENCODING: DECODE UTF-8 FROM LATIN1/WINDOWS-1252 ---
function decodeUtf8(str) {
  if (typeof str !== 'string') return str;
  try {
    return decodeURIComponent(escape(str));
  } catch (e) {
    return str;
  }
}
function cleanRow(obj) {
  if (!obj || typeof obj !== 'object') return obj;
  const newObj = {};
  for (const [k, v] of Object.entries(obj)) {
    if (typeof v === 'string') {
      newObj[k] = decodeUtf8(v);
    } else if (Array.isArray(v)) {
      newObj[k] = v.map(cleanRow);
    } else if (typeof v === 'object' && v !== null) {
      newObj[k] = cleanRow(v);
    } else {
      newObj[k] = v;
    }
  }
  return newObj;
}
payload = payload.map(cleanRow);


// 0. Extract Metadata
let uiTemplate = 'DEFAULT';
const metaIdx = payload.findIndex(r => r.Metadata_UiTemplate !== undefined);
if (metaIdx !== -1) {
  uiTemplate = payload[metaIdx].Metadata_UiTemplate;
  if (uiTemplate === 'CART') {
    payload[metaIdx] = { 
      success: true, 
      MaKhachHang: payload[metaIdx].MaKhachHang,
      ItemList: payload[metaIdx].ItemList
    };
  } else {
    payload.splice(metaIdx, 1);
  }
}

// Xu ly SQL FOR JSON PATH output (khi SP khong tim thay trong API_Definition)
// N8N MS SQL tra ve [{JSON_F52E...: '[{"code":2,"msg":"..."}]'}]
if (payload.length === 1 && payload[0][JSON_KEY] !== undefined) {
  try {
    const inner = JSON.parse(payload[0][JSON_KEY]);
    if (Array.isArray(inner) && inner.length > 0) {
      if (inner[0].code === 1 || inner[0].code === 2) {
        return [{ json: { reply: inner[0].msg || 'ApiCode chua duoc dang ky trong he thong', status: 'error', data: [], uiTemplate: uiTemplate } }];
      }
      payload = inner;
    }
  } catch(e) {
    return [{ json: { reply: 'Loi xu ly ket qua SQL', status: 'error', data: [], uiTemplate: uiTemplate } }];
  }
  if (payload.length === 1 && payload[0][JSON_KEY] !== undefined) {
    return [{ json: { reply: 'Khong tim thay API phu hop', status: 'error', data: [], uiTemplate: uiTemplate } }];
  }
}

// Kiem tra loi don gian {code, msg}
if (payload.length === 1 && (payload[0].code === 1 || payload[0].code === 2 || payload[0].error)) {
  return [{ json: { reply: payload[0].msg || payload[0].error || 'Loi khong xac dinh', status: 'error', data: [], uiTemplate: uiTemplate } }];
}

// Loc bo cac row con JSON_KEY hoac object rong do n8n MS SQL alwaysOutputData: true tra ve
payload = payload.filter(r => {
  if (!r) return false;
  if (r[JSON_KEY] !== undefined) return false;
  const keys = Object.keys(r).filter(k => k !== 'JSON_KEY');
  return keys.length > 0;
});

if (payload.length === 0) {
  return [{ json: { reply: 'Khong tim thay du lieu', status: 'success', count: 0, data: [], uiTemplate: uiTemplate } }];
}

// --- DATA BYPASS CỦA GIAI ĐOẠN 2 ---
let isAgent = false;
