}
return [{ json: { ...input, validation: {
  ok: uniqueErrors.length === 0,
  httpStatus: uniqueErrors.length === 0 ? 200 : 422,
  code: uniqueErrors.length === 0 ? 'OK' : 'VALIDATION_ERROR',
  message: validationMessage,
  fields: uniqueErrors
} } }];

